shaders.chromatic:
        #pragma header

        #define texture flixel_texture2D

        uniform float amount;

    vec2 PincushionDistortion(in vec2 uv, float strength) 
    {
	    vec2 st = uv - 0.5;
        float uvA = atan(st.x, st.y);
        float uvD = dot(st, st);
        return 0.5 + vec2(sin(uvA), cos(uvA)) * sqrt(uvD) * (1.0 - strength * uvD);
    }

    vec3 ChromaticAbberation(sampler2D tex, in vec2 uv) 
    {
	    float rChannel = texture(tex, PincushionDistortion(uv, 0.3 * amount)).r;
        float gChannel = texture(tex, PincushionDistortion(uv, 0.15 * amount)).g;
        float bChannel = texture(tex, PincushionDistortion(uv, 0.075 * amount)).b;
        vec3 retColor = vec3(rChannel, gChannel, bChannel);
        return retColor;
    }

    void main()
    {
        vec2 uv = openfl_TextureCoordv;
        vec3 col = ChromaticAbberation(bitmap, uv);

        gl_FragColor = vec4(col, 1.0);
    }

shaders.heatwave:
#pragma header

        uniform float iTime;

        uniform sampler2D distortTexture;

        void main(){
                vec2 p_m = openfl_TextureCoordv;
                vec2 p_d = p_m;

                p_d.t -= iTime * 0.05;
                p_d.t = mod(p_d.t, 1.0);

                vec4 dst_map_val = flixel_texture2D(distortTexture, p_d);

                vec2 dst_offset = dst_map_val.xy;
                dst_offset -= vec2(.5,.5);
                dst_offset *= 2.;
                dst_offset *= 0.009; //THIS CONTROLS THE INTENSITY [higher numbers = MORE WAVY]

                //reduce effect towards Y top
                dst_offset *= pow(p_m.t, 1.4); //THIS CONTROLS HOW HIGH UP THE SCREEN THE EFFECT GOES [higher numbers = less screen space]

                vec2 dist_tex_coord = p_m.st + dst_offset;
                gl_FragColor = flixel_texture2D(bitmap, dist_tex_coord); 
        }

shaders.sky:
#pragma header

      uniform float iTime;

      void main(void) {
        gl_FragColor = flixel_texture2D(
          bitmap,
          vec2(
            openfl_TextureCoordv.x,
            fract(openfl_TextureCoordv.y + iTime * 0.05)
          )
        );
      }

shaders.sun:
#pragma header

      uniform float iTime;

      void main(void) {
        vec2 uv = openfl_TextureCoordv.xy;
        float waveX = sin(uv.y * 90.0 + iTime * 4.5) * 0.003;
        float waveY = cos(uv.x * 90.0 + iTime * 4.5) * 0.003;

        gl_FragColor = flixel_texture2D(bitmap, clamp(uv + vec2(waveX, waveY), 0.0, 1.0));
      }

shaders.water:
#pragma header

      #define round(a) floor(a + 0.5)
      #define time iTime * 0.1
      #define DAMP 1.5

      uniform float iTime;

      float rand2D( vec2 uv ) {
        return fract(sin(dot(uv.xy, vec2(12.9898,78.233))) * 43758.5453123);
      }

      vec3 rand3( vec2 uv ) {
        return vec3 ( rand2D(fract(uv) ), rand2D(fract(uv + vec2(0.1))), rand2D( fract(uv - vec2( 0.1 ) )) );
      }

      vec3 rand3r( float r, vec2 uv ) {
        return rand3( round(uv * r)/r );
      }

      void main(void) {
        if (openfl_TextureCoordv.y < 0.4160475483)
        {
          gl_FragColor = vec4(0.0);
          return;
        }

        vec2 uv = openfl_TextureCoordv.xy;
        vec2 a = uv;

        uv.x += DAMP * 0.02 * sin( uv.x * 7.365225+ time *-3.274389);
        uv.y += DAMP * ( 1.-a.y )* 0.02 * cos( uv.y * -5. + time * 2.3142597644);

        uv.y += sin(iTime*3.0) * 0.005;
        uv.y += cos(uv.x * 10.0 + iTime * 4.5) * 0.006;

        uv.x = mix( uv.x, a.x, pow(2.0* abs(0.5- a.x),3.0));
        uv.y = mix( uv.y, a.y, pow(2.0* abs(0.5- a.y),3.0));

        vec3 te = rand3r(15., uv + vec2(iTime * 0.08) );
        vec3 t3 = rand3r(10., uv - vec2 (uv.y * cos(0.0344 * iTime), uv.x * sin(-.0453 * iTime) ) - vec2(iTime * 0.02454945) );

        uv.x = fract(uv.x + time * 0.5);
        uv = uv + te.xy * 0.003 - t3.yz * 0.005;
        uv.x = fract(uv.x);

        gl_FragColor = flixel_texture2D(bitmap, uv);
        gl_FragColor.rgb *= mix( vec3(1.), rand3r( 100.0, uv + te.xy * 0.003 - t3.yz * 0.005 + vec2(time)), 0.04);
      }
